import{_ as e,c as t,o,a5 as r}from"./chunks/framework.BLFC1wTn.js";const m=JSON.parse('{"title":"Server Net","description":"","frontmatter":{},"headers":[],"relativePath":"pages/interview/server/index.md","filePath":"pages/interview/server/index.md","lastUpdated":1730020210000}'),i={name:"pages/interview/server/index.md"},n=r('<h1 id="server-net" tabindex="-1">Server Net <a class="header-anchor" href="#server-net" aria-label="Permalink to &quot;Server Net&quot;">​</a></h1><h2 id="跨域问题和同源策略" tabindex="-1">跨域问题和同源策略 <a class="header-anchor" href="#跨域问题和同源策略" aria-label="Permalink to &quot;跨域问题和同源策略&quot;">​</a></h2><ol><li><strong>同源</strong>，用于限制一个origin文档或者它加载的脚本如何能与另一个源的资源进行交互，能阻隔恶意文档，减少攻击。协议、域名/ip、端口都相同，即为同源。PS：同源策略下，服务器可以接收浏览器发来的请求，拦截的是服务器返回的数据。非同源不能相互操作DOM，不能互相读写Storage、Cookies等，不能通过AJAX的方式相互发送、接收数据；由于同源策略的限制，浏览器会阻止跨域请求，这包括Ajax请求、跨域资源嵌入（如&lt; img &gt;、&lt; script &gt;、&lt; iframe &gt;等）、跨域Cookie读取等操作。</li><li><strong>跨域</strong>，由同源策略引发的开发问题，称为跨域问题。解决主流为CORS、代理两种。 <ul><li><strong>CORS</strong>：CORS是一套同于检验浏览器跨域请求的机制，基本理念是：只要服务器没有明确表示允许，则校验失败。需要后端解决。将请求分为简单请求和预检请求。不支持IE10以下 <ul><li><strong>简单请求</strong>：请求方式为GET、HEAD、POST；Content-Type为text/plain，multipart/form-data/ ，application/x-www-form-urlencoded之一；头部字段不超出为Accept、Accept-Language、Content-Language；</li><li><strong>预检请求</strong>：除简单请求外，浏览器会发一个预检请求检测请求是否通过。</li></ul></li></ul></li><li><strong>浏览器检测跨域原理</strong>，浏览器检测到 ajax 请求的域与当前域不一致，会在请求头中增加 Origin 字段，然后检查服务端响应头 Access-Control-Allow-Origin，如果不存在或不匹配，则报跨域错误</li><li><strong>携带cookie跨域</strong>，Access-Control-Allow-Origin 直接设置为通配符 * 时是无法通过浏览器的检查的，此时该响应头的值必须与发出请求的域完全匹配才行，另外，还需要设置 Access-Control-Allow-Credentials 响应头的值为 true，表示支持带 cookie 的跨域请求。</li><li><strong>反向代理</strong>，服务器代理客户端的请求，原理：服务器与服务器之间没有跨域问题，在nginx中配置location路径。优点：1.负载均衡:将请求分发到多个后端服务器上；2.安全性，可以隐藏后端服务器的真实IP；缓存：可以缓存静态资源</li><li><strong>JSONP</strong>，<code>&lt;script&gt; </code>标签的 src 属性却可以加载跨域的 JavaScript 脚本，JSONP 就是利用这一特性实现的。与普通的 Ajax 请求不同，在使用 JSONP 进行跨域请求时，服务器不再返回 JSON 格式的数据，而是将返回的数据包装成一个函数调用并返回给客户端，客户端再执行这个函数，来实现跨域。JSONP 的优点是兼容性好，在一些老旧的浏览器种也可以运行，但它的缺点也非常明显，那就是只能进行 GET 请求</li><li><strong>postMessage</strong>:只支持GET</li><li><strong>domain</strong>：cookie跨域，document.domain,可允许子域名页面跨域</li></ol>',3),a=[n];function s(l,c,g,d,p,_){return o(),t("div",null,a)}const u=e(i,[["render",s]]);export{m as __pageData,u as default};
